pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 putAmount, uint256 unlockTime, uint256 collectAmount, uint256 callerSeed) public {
        // Bound amounts to avoid overflow in the test setup itself, but keep wide.
        putAmount = bound(putAmount, 0, type(uint128).max);
        collectAmount = bound(collectAmount, 0, type(uint128).max);
        unlockTime = bound(unlockTime, block.timestamp, type(uint64).max);
        address actor = address(uint160(callerSeed));
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Give actor some ether
        vm.deal(actor, putAmount);
        // Put
        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        // Warp past unlock time
        vm.warp(unlockTime + 1);

        // Record balance before collect
        ( , uint256 balanceBefore) = c.Acc(actor);

        // Collect
        vm.prank(actor);
        bool ok = true;
        try c.Collect(collectAmount) {
        } catch {
            ok = false;
        }

        // Read balance after collect
        ( , uint256 balanceAfter) = c.Acc(actor);

        // General rule: If collect succeeded, the balance must not have increased.
        if (ok) {
            assertTrue(balanceAfter <= balanceBefore);
        } else {
            // If collect reverted, balance must remain unchanged.
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

