pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(address(this));
        // deploy a Log contract as C expects, but we don't assert on it
    }

    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 deposit3) public {
        // bound to avoid overflow in test setup but keep wide enough to trigger the bug
        deposit1 = bound(deposit1, 0, 10000 ether);
        deposit2 = bound(deposit2, 0, 10000 ether);
        deposit3 = bound(deposit3, 0, 10000 ether);

        address user1 = address(0x1);
        address user2 = address(0x2);

        // fund users
        vm.deal(user1, deposit1 + deposit2 + deposit3);
        vm.deal(user2, deposit1 + deposit2 + deposit3);

        // user1 deposits
        vm.prank(user1);
        c.Put{value: deposit1}(block.timestamp + 1000);

        // user2 deposits
        vm.prank(user2);
        c.Put{value: deposit2}(block.timestamp + 1000);

        // user1 deposits again
        vm.prank(user1);
        c.Put{value: deposit3}(block.timestamp + 1000);

        // invariant: contract balance >= sum of all user balances
        uint256 sumBalances = c.Acc(user1).balance + c.Acc(user2).balance;
        assertTrue(address(c).balance >= sumBalances);
    }
}

