pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract ReentrantAttacker {
    C public target;
    uint256 public attackAmount;
    bool public attackPrepared;
    uint256 public reentryCount;

    constructor(C _target) {
        target = _target;
    }

    function prepareAttack(uint256 _amount) external payable {
        require(msg.value == _amount);
        attackAmount = _amount;
        attackPrepared = true;
    }

    function startAttack() external {
        require(attackPrepared);
        attackPrepared = false;
        reentryCount = 0;
        target.Collect(attackAmount);
    }

    receive() external payable {
        if (reentryCount < 1) {
            reentryCount++;
            target.Collect(attackAmount);
        }
    }
}

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C(address(this));
        attacker = new ReentrantAttacker(c);
    }

    function testFuzz_property(uint256 depositAmount, uint256 attackAmount) public {
        vm.assume(depositAmount >= attackAmount);
        vm.assume(attackAmount > 0);
        vm.assume(depositAmount <= type(uint128).max);

        // Fund attacker and deposit via Put
        vm.deal(address(attacker), depositAmount + attackAmount);
        vm.prank(address(attacker));
        c.Put{value: depositAmount}(0);

        // Warp to unlock funds
        vm.warp(block.timestamp + 1);

        // Prepare attack: attacker sends additional Ether to increase balance
        vm.prank(address(attacker));
        attacker.prepareAttack{value: attackAmount}(attackAmount);

        uint256 balanceBefore = address(attacker).balance;

        // Trigger reentrancy
        vm.prank(address(attacker));
        attacker.startAttack();

        uint256 balanceAfter = address(attacker).balance;

        // Property: Ether withdrawn by attacker via Collect should not exceed the total Ether originally sent via Put
        // (balanceAfter - balanceBefore) <= depositAmount
        // The original contract satisfies this because reentrancy is blocked.
        assertTrue(balanceAfter - balanceBefore <= depositAmount);
    }
}

