pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime) public {
        // Bound amounts to prevent overflow/underflow in the contract's safe math, keep domain wide
        amount1 = bound(amount1, 1, 1000 ether);
        amount2 = bound(amount2, 1, 1000 ether);
        unlockTime = bound(unlockTime, 1, type(uint64).max);

        // Deploy a re-entrant attacker helper that calls Put back within Collect
        ReentrantAttacker attacker = new ReentrantAttacker();
        address attackerAddr = address(attacker);

        // Fund the attacker with enough Ether for Put calls plus gas
        vm.deal(attackerAddr, amount1 + amount2 + 10 ether);

        // Attacker makes initial Put, setting up balance and unlockTime
        vm.prank(attackerAddr);
        c.Put{value: amount1}(unlockTime);

        // Record attacker's balance after first Put
        uint256 balanceAfterFirstPut = c.Acc(attackerAddr).balance;

        // Warp past unlockTime to allow Collect
        vm.warp(block.timestamp + unlockTime + 1);

        // Set up re-entrant target: attacker will call back into Put with amount2 during Collect
        attacker.setTarget(address(c));
        attacker.setAmount(amount2);

        // Attacker calls Collect which triggers re-entrant Put via attacker's fallback
        vm.prank(attackerAddr);
        try c.Collect(balanceAfterFirstPut) { } catch { }

        // After the whole transaction, total Ether sent by attacker is amount1 (initial) + amount2 (re-entrant)
        uint256 totalSent = amount1 + amount2;
        // Acc[attacker].balance should equal totalSent, but mutant credits re-entrant Put without Ether
        assertTrue(c.Acc(attackerAddr).balance == totalSent);
    }
}

contract ReentrantAttacker {
    address target;
    uint256 amount;
    bool locked;

    function setTarget(address _target) external {
        target = _target;
    }
    function setAmount(uint256 _amount) external {
        amount = _amount;
    }

    fallback() external payable {
        if (!locked) {
            locked = true;
            (bool success, ) = target.call{value: amount}(abi.encodeWithSignature("Put(uint256)", 0));
            locked = false;
        }
    }
}

