pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint128 depositAmount, uint128 collectAmount) public {
        // Ensure unlockTime is in the future, and amounts are within reasonable bounds
        vm.assume(unlockTime > block.timestamp);
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);
        // Deposit must be at least MinSum (1 ether) to allow collection; ensure it's enough
        vm.assume(depositAmount >= 1 ether);

        address user = address(0x1234);
        vm.deal(user, depositAmount);

        // First deposit via Put with a future unlockTime
        vm.prank(user);
        c.Put{value: depositAmount}(unlockTime);

        // Warp to a time after deposit but before unlockTime, so Collect should fail in reference
        // The bug allows premature collection because unlockTime remains 0 (block.timestamp at deposit is < unlockTime)
        // We warp to a time that is strictly after deposit and strictly before unlockTime.
        vm.warp(unlockTime - 1);

        // Ensure MinSum is met (already done via vm.assume)
        // Try to collect, expecting revert in reference but success in mutant
        bool ok;
        vm.prank(user);
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference reverts (ok == false) because block.timestamp < unlockTime;
        // The mutant does not revert because unlockTime was never updated and remains 0, so block.timestamp > 0.
        // Thus the invariant: for any future unlockTime, Collect before unlockTime must revert.
        assertTrue(!ok);
    }
}

