contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, uint256 warpDays) public {
        // Keep deposit within sensible bounds
        depositAmt = bound(depositAmt, 1 ether, 100 ether);
        // The collect amount must be at least MinSum (1 ether) and at most the deposit
        vm.assume(collectAmt >= 1 ether);
        vm.assume(collectAmt <= depositAmt);
        // Warp forward by at least 1 day (past the unlock time)
        warpDays = bound(warpDays, 1, 365);

        // Deploy a helper that always reverts on receiving Ether, otherwise the call
        // succeeds and we cannot test the balance invariant for a successful Collect.
        // Actually we need a successful low-level call to trigger the mutant path.
        // A fuzzed address always succeeds, so we just use address(this) (an EOA) as
        // the caller; that call always succeeds. No adversarial helper needed here.
        address actor = address(0x1234);
        vm.deal(actor, depositAmt);

        vm.prank(actor);
        c.Put{value: depositAmt}(uint256(block.timestamp + 1 days));

        (, uint256 preBalance) = c.Acc(actor);

        vm.warp(block.timestamp + warpDays * 1 days);

        uint256 preEth = actor.balance;

        vm.prank(actor);
        c.Collect(collectAmt);

        (, uint256 postBalance) = c.Acc(actor);
        uint256 received = actor.balance - preEth;

        // For a correct implementation, postBalance = preBalance - collectAmt.
        // Therefore postBalance + received = preBalance.
        // The mutant fails to subtract, so postBalance = preBalance,
        // making postBalance + received > preBalance.
        // We assert the expected invariant: postBalance + received <= preBalance
        assertTrue(postBalance + received <= preBalance);
    }
}

